/ {
	test_domain: test_domain {
		compatible = "test-power-domain-controller";
		#power-domain-cells = <1>;
	};

	test_dev_a: test_dev_a {
		power-domains = <&test_domain 0>;
		compatible = "test-device-a";
	};
};
